import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十五卦 晋 火地晋 离上坤下","description":"周易 - 第三十五卦 晋 火地晋 离上坤下","frontmatter":{"title":"第三十五卦 晋 火地晋 离上坤下","description":"周易 - 第三十五卦 晋 火地晋 离上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/036.md","filePath":"zh/classics/zhouyi/036.md"}'),l={name:"zh/classics/zhouyi/036.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="晋" tabindex="-1">晋 <a class="header-anchor" href="#晋" aria-label="Permalink to “晋”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>康侯用锡马蕃庶，昼日三接。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>晋，进也。明出地上，顺而丽乎大明，柔进而上行。是以康侯用锡马蕃庶，昼日三接也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>明出地上，晋；君子以自昭明德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>晋如，摧如，贞吉。罔孚，裕无咎。象 曰：晋如，摧如；独行正也。裕无咎；未受命也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>晋如，愁如，贞吉。受兹介福，于其王母。象曰：受之介福，以中正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>众允，悔亡。象曰：众允之，志上行也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>晋如硕鼠，贞厉。象曰：硕鼠贞厉，位不当也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>悔亡，失得勿恤，往吉无不利。象曰：失得勿恤，往有庆也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>晋其角，维用伐邑，厉吉无咎，贞吝。象曰：维用伐邑，道未光也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
